select jsonb_build_object(
 'schemas',(select jsonb_agg(jsonb_build_array(nspname,pg_get_userbyid(nspowner),nspacl::text) order by nspname) from pg_namespace where nspname in('public','private','auth','extensions')),
 'relations',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,c.relkind,pg_get_userbyid(c.relowner),c.relacl::text,c.relrowsecurity,c.relforcerowsecurity,c.reloptions,c.relpersistence) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','private','auth','extensions')),
 'columns',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,a.attnum,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,a.attisdropped,pg_get_expr(d.adbin,d.adrelid)) order by n.nspname,c.relname,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where n.nspname in('public','private','auth','extensions') and a.attnum>0),
 'functions',(select jsonb_agg(jsonb_build_array(n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),md5(pg_get_functiondef(p.oid)),pg_get_userbyid(p.proowner),p.proacl::text,p.proconfig) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','private','auth','extensions') and p.prokind in('f','p')),
 'constraints',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,x.conname,x.contype,x.convalidated,x.condeferrable,x.condeferred,pg_get_constraintdef(x.oid)) order by n.nspname,c.relname,x.conname) from pg_constraint x join pg_class c on c.oid=x.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','private','auth','extensions')),
 'indexes',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,i.indexrelid::regclass::text,pg_get_indexdef(i.indexrelid),i.indisvalid,i.indisready) order by n.nspname,c.relname,i.indexrelid::regclass::text) from pg_index i join pg_class c on c.oid=i.indrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','private','auth','extensions')),
 'triggers',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,t.tgname,t.tgenabled,t.tgisinternal,pg_get_triggerdef(t.oid)) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','private','auth','extensions')),
 'policies',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,p.polname,p.polcmd,p.polpermissive,p.polroles::text,pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid)) order by n.nspname,c.relname,p.polname) from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','private','auth','extensions')),
 'defaults',(select jsonb_agg(jsonb_build_array(coalesce(n.nspname,'global'),pg_get_userbyid(d.defaclrole),d.defaclobjtype,d.defaclacl::text) order by coalesce(n.nspname,'global'),pg_get_userbyid(d.defaclrole),d.defaclobjtype) from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace where n.nspname in('public','private','auth','extensions') or n.oid is null),
 'sequences',(select jsonb_agg(to_jsonb(s) order by schemaname,sequencename) from pg_sequences s where schemaname in('public','private','auth','extensions')),
 'extensions',(select jsonb_agg(jsonb_build_array(e.extname,e.extversion,n.nspname,pg_get_userbyid(e.extowner)) order by e.extname) from pg_extension e join pg_namespace n on n.oid=e.extnamespace),
 'revisions',(select jsonb_agg(to_jsonb(r) order by company_id,domain) from private.agent_read_domain_revisions r),
 'expenses',(select jsonb_agg(to_jsonb(e) order by id) from public.expenses e),
 'batches',(select jsonb_agg(to_jsonb(b) order by id) from public.expense_batches b),
 'allocations',(select jsonb_agg(to_jsonb(a) order by id) from public.expense_project_allocations a),
 'save_requests',(select jsonb_agg(to_jsonb(r) order by request_id) from private.expense_save_requests r),
 'notifications',(select jsonb_agg(to_jsonb(n) order by id) from public.notifications n),
 'queue',(select jsonb_agg(to_jsonb(q) order by id) from public.accounting_sync_queue q)
)::text;
